"use client"

import { createParts } from "@ui-sdk/react/primitive"
import {
  createSliderController,
  Slider,
  SliderControl,
  SliderThumb,
  SliderTrack,
  type SliderValueChangeDetails,
} from "@ui-sdk/react/slider"
import { memo, useRef, useState, type PointerEvent as ReactPointerEvent } from "react"

import {
  angleAt,
  colourAt,
  colourName,
  readingAt,
  wavelengthAtAngle,
  type ColourNames,
} from "@/components/ui/prism-picker-dial"
import { maxWavelength, minWavelength } from "@/components/ui/prism-picker-optics"
import { prismPicker } from "@/components/ui/prism-picker-primitive"
import { ringRadius, stageCentre } from "@/components/ui/prism-picker-scene"
import { usePrismPickerScene } from "@/components/ui/use-prism-picker-scene"
import { cn, cssVars } from "@/lib/utils"

const { Root: PrismPickerRoot } = createParts(prismPicker, { root: "div" })

type PrismPickerLabels = {
  /** Names the dial, a slider in nanometres, for screen readers and agents. */
  dial: string
  /** The readout's terms. */
  hex: string
  wavelength: string
  hue: string
  prism: string
  /** The colour names the value text and the readout use, by hue. */
  names: ColourNames
}

const prismPickerLabels: PrismPickerLabels = {
  dial: "Wavelength",
  hex: "Hex",
  wavelength: "Wavelength",
  hue: "Hue",
  prism: "Prism",
  names: {
    red: "red",
    orange: "orange",
    yellow: "yellow",
    green: "green",
    cyan: "cyan",
    blue: "blue",
    violet: "violet",
  },
}

/** The picked colour: the sRGB hex the rays and swatch show, its hues, and the wavelength behind it. */
type PrismColor = { hex: string; oklchHue: number; hslHue: number; wavelength: number }

type PrismPickerState = { disabled: boolean }

type PrismPickerProps = {
  /** The accessible name of the picker as a whole. */
  label: string
  /** The picked wavelength in nm, a whole number from 380 to 700. Pass it to control the picker. */
  value?: number
  defaultValue?: number
  /** Runs on every step of a drag or a key, with UI SDK's slider details (`reason`, `source`, `cancel()`). */
  onValueChange?: (value: number, details: SliderValueChangeDetails) => void
  /** Runs once a drag or a key press that changed the value ends, for saving. */
  onValueCommit?: (value: number) => void
  /** Runs with the colour on every change, with the same details. */
  onColorChange?: (color: PrismColor, details: SliderValueChangeDetails) => void
  disabled?: boolean
  /** Submits the wavelength under this name in a form. */
  name?: string
  /** Overrides any label; `names` overrides colour names one by one. */
  labels?: Partial<Omit<PrismPickerLabels, "names">> & { names?: Partial<ColourNames> }
  /** Classes for the root; a function gets the picker's state. */
  className?: string | ((state: PrismPickerState) => string | undefined)
  /** Called with each canvas paint's duration in ms, for measuring. */
  onPaint?: (milliseconds: number) => void
}

const prismColor = (wavelength: number): PrismColor => {
  const colour = colourAt(wavelength)
  return { hex: colour.hex, oklchHue: colour.hue, hslHue: colour.hslHue, wavelength }
}

const signed = (value: number) => `${value < 0 ? "−" : ""}${Math.abs(value).toFixed(1)}`

const ticks = Array.from({ length: (maxWavelength - minWavelength) / 10 + 1 }, (_, index) => minWavelength + index * 10)
const numbered = [450, 500, 550, 600, 650]
const arcSegments = Array.from({ length: 80 }, (_, index) => {
  const from = minWavelength + index * 4
  return { from, to: from + 4, colour: colourAt(from).hex }
})

const polar = (angle: number, radius: number) => {
  const radians = (angle * Math.PI) / 180
  return { x: radius * Math.cos(radians), y: radius * Math.sin(radians) }
}

function arcPath(from: number, to: number, radius: number) {
  const start = polar(angleAt(from), radius)
  const end = polar(angleAt(to), radius)
  return `M ${start.x.toFixed(2)} ${start.y.toFixed(2)} A ${String(radius)} ${String(radius)} 0 0 0 ${end.x.toFixed(2)} ${end.y.toFixed(2)}`
}

// The engraved scale: the ring is 100 units in a 260-unit square, so the CSS sizes it from the ring's radius.
const DialScale = memo(function DialScale() {
  return (
    // oxlint-disable-next-line eskais/no-inline-icons -- an instrument's engraved scale, not an icon
    <svg data-slot="prism-scale" aria-hidden="true" viewBox="-130 -130 260 260">
      <circle r="100" fill="none" stroke="currentColor" strokeOpacity="0.1" strokeWidth="0.6" />
      <circle r="100" fill="none" stroke="currentColor" strokeOpacity="0.05" strokeWidth="14" />
      {arcSegments.map(({ from, to, colour }) => (
        <path key={from} d={arcPath(from, to, 93)} fill="none" strokeWidth="1.6" stroke={colour} strokeOpacity="0.85" />
      ))}
      {ticks.map((nanometres) => {
        const major = nanometres % 50 === 0
        const inner = polar(angleAt(nanometres), 104)
        const outer = polar(angleAt(nanometres), major ? 112 : 108)
        return (
          <line
            key={nanometres}
            x1={inner.x}
            y1={inner.y}
            x2={outer.x}
            y2={outer.y}
            stroke="currentColor"
            strokeOpacity={major ? 0.55 : 0.22}
            strokeWidth={major ? 0.9 : 0.6}
          />
        )
      })}
    </svg>
  )
})

function pointerOnDial(event: ReactPointerEvent<HTMLElement>) {
  const rect = event.currentTarget.getBoundingClientRect()
  const x = event.clientX - (rect.left + rect.width * stageCentre.x)
  const y = event.clientY - (rect.top + rect.height * stageCentre.y)
  return {
    angle: (Math.atan2(y, x) * 180) / Math.PI,
    distance: Math.hypot(x, y),
    ring: ringRadius(rect.width, rect.height),
  }
}

type Drag = { pointer: number; relative: boolean; from: number; dial: number }

/**
 * A hue picker built on a prism: a white beam refracts through glass the dial turns, and the wavelength that leaves
 * through the fixed exit slit is the colour. The dial is UI SDK's slider in nanometres (arrows, Page Up and Down,
 * Home and End); a drag on the ring or on the prism turns it. Spectral colours only, 380 to 700 nm.
 */
function PrismPicker({
  label,
  value,
  defaultValue = 520,
  onValueChange,
  onValueCommit,
  onColorChange,
  disabled = false,
  name,
  labels: labelOverrides,
  className,
  onPaint,
}: PrismPickerProps) {
  const labels = { ...prismPickerLabels, ...labelOverrides }
  const names = { ...prismPickerLabels.names, ...labelOverrides?.names }
  const [slider] = useState(() => createSliderController<number>())
  const [ownValue, setOwnValue] = useState(defaultValue)
  const wavelength = value ?? ownValue
  const [instant, setInstant] = useState(false)
  const [dragging, setDragging] = useState(false)
  const stage = useRef<HTMLDivElement>(null)
  const light = useRef<HTMLCanvasElement>(null)
  const [canvases] = useState(() => ({ stage, light }))
  const drag = useRef<Drag | null>(null)
  usePrismPickerScene(canvases, { wavelength, instant, onPaint })

  const reading = readingAt(wavelength)
  // What the server renders, before the hook sets the knob's own angle and colour; it never changes after, so a key
  // press doesn't restyle the stage.
  const [firstPaint] = useState(() => ({ colour: reading.colour.hex, dial: `${String(angleAt(wavelength))}deg` }))
  const colourNameOf = (nanometres: number) => colourName(colourAt(nanometres).hue, names)

  const moveTo = (event: ReactPointerEvent<HTMLElement>) => {
    const current = drag.current
    if (!current) return
    const { angle, distance } = pointerOnDial(event)
    if (current.relative && distance < 8) return
    const delta = ((((angle - current.from + 180) % 360) + 360) % 360) - 180
    const dial = current.relative ? current.dial + delta : angle
    if (current.relative) {
      current.from = angle
      current.dial = dial
    }
    const next = wavelengthAtAngle(dial, slider.getValue())
    if (next !== slider.getValue()) slider.setValue(next, { reason: "drag", event: event.nativeEvent })
  }

  const onPointerDown = (event: ReactPointerEvent<HTMLElement>) => {
    if (disabled || event.button !== 0) return
    const { angle, distance, ring } = pointerOnDial(event)
    // The ring takes a press across a band 48px wide; inside it, the prism turns from where it's grabbed.
    const onRing = Math.abs(distance - ring) <= 24
    if (!onRing && distance > ring - 24) return
    event.preventDefault()
    event.currentTarget.setPointerCapture(event.pointerId)
    drag.current = { pointer: event.pointerId, relative: !onRing, from: angle, dial: angleAt(slider.getValue()) }
    setDragging(true)
    slider.focus()
    if (onRing) moveTo(event)
  }

  const endDrag = (event: ReactPointerEvent<HTMLElement>) => {
    if (drag.current?.pointer !== event.pointerId) return
    drag.current = null
    setDragging(false)
  }

  const onChange = (next: number, details: SliderValueChangeDetails) => {
    onValueChange?.(next, details)
    if (details.canceled) return
    setInstant(details.reason === "drag")
    setOwnValue(next)
    onColorChange?.(prismColor(next), details)
  }

  return (
    <PrismPickerRoot
      slider={slider}
      disabled={disabled}
      aria-label={label}
      className={cn(
        "flex w-full flex-col overflow-hidden rounded-surface border bg-card text-card-foreground shadow-surface",
        typeof className === "function" ? className({ disabled }) : className,
      )}
    >
      <div
        ref={stage}
        data-slot="prism-stage"
        data-dragging={dragging ? "" : undefined}
        data-disabled={disabled ? "" : undefined}
        onPointerDown={onPointerDown}
        onPointerMove={moveTo}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
        style={cssVars({
          "--prism-picked": firstPaint.colour,
          "--prism-dial": firstPaint.dial,
        })}
      >
        <div data-slot="prism-grip" aria-hidden="true" />
        <canvas ref={light} data-slot="prism-light" aria-hidden="true" />
        <DialScale />
        {numbered.map((nanometres) => (
          <span
            key={nanometres}
            data-slot="prism-tick"
            aria-hidden="true"
            style={cssVars({ "--prism-tick-angle": `${String(angleAt(nanometres))}deg` })}
          >
            {nanometres}
          </span>
        ))}
        <Slider
          controller={slider}
          value={wavelength}
          onValueChange={onChange}
          onValueCommit={onValueCommit ? (next: number) => onValueCommit(next) : undefined}
          min={minWavelength}
          max={maxWavelength}
          step={1}
          largeStep={10}
          disabled={disabled}
          name={name}
          format={(next: number) => `${String(next)} nm, ${colourNameOf(next)}`}
          className="pointer-events-none absolute inset-0"
        >
          <SliderControl className="absolute inset-0">
            <SliderTrack className="absolute inset-0">
              <SliderThumb aria-label={labels.dial} className="touch-target" />
            </SliderTrack>
          </SliderControl>
        </Slider>
      </div>
      <dl className="flex flex-wrap items-start gap-group p-inset-surface">
        <div
          data-slot="prism-colour"
          style={cssVars({ "--prism-picked": reading.colour.hex })}
          className="min-w-40 grow basis-0 gap-x-items"
        >
          <dt className="sr-only">{labels.hex}</dt>
          <dd className="font-mono text-title-sm tracking-tight uppercase">{reading.colour.hex}</dd>
          <dd className="text-caption text-muted-foreground">{colourName(reading.colour.hue, names)}</dd>
        </div>
        <div className="flex grow basis-0 flex-col">
          <dt className="text-meta tracking-meta text-muted-foreground uppercase">{labels.wavelength}</dt>
          <dd className="font-mono text-body tabular-nums">{`${String(Math.round(wavelength))} nm`}</dd>
        </div>
        <div className="flex grow basis-0 flex-col">
          <dt className="text-meta tracking-meta text-muted-foreground uppercase">{labels.hue}</dt>
          <dd className="font-mono text-body tabular-nums">
            {`${String(Math.round(reading.colour.hue))}°`}{" "}
            <span className="text-caption text-muted-foreground">OKLCH</span>
          </dd>
          <dd className="font-mono text-caption text-muted-foreground tabular-nums">
            {`${String(Math.round(reading.colour.hslHue))}° HSL`}
          </dd>
        </div>
        <div className="flex grow basis-0 flex-col">
          <dt className="text-meta tracking-meta text-muted-foreground uppercase">{labels.prism}</dt>
          <dd className="font-mono text-body tabular-nums">{`${signed(reading.rotation)}°`}</dd>
        </div>
      </dl>
    </PrismPickerRoot>
  )
}

export { PrismPicker, prismPickerLabels }
export type { PrismColor, PrismPickerLabels, PrismPickerProps, PrismPickerState }

import { definePrimitive } from "@ui-sdk/core"
import type { createSliderController } from "@ui-sdk/core/slider"

import { maxWavelength, minWavelength, wavelengthAtHue } from "@/components/ui/prism-picker-optics"
import { settled, unavailable } from "@/lib/action-refusal"

type PrismSlider = Pick<ReturnType<typeof createSliderController<number>>, "getValue" | "setValue">

type PrismPickerOptions = {
  slider?: PrismSlider
  disabled?: boolean
}

type Call = { action: string; event: Event | undefined }

const toWavelength = (slider: PrismSlider, wavelength: number, { action, event }: Call) => {
  if (slider.getValue() === wavelength) return true
  return settled(slider.setValue(wavelength, { reason: "imperative", event }), action, { event })
}

function ready(options: PrismPickerOptions, { action, event }: Call) {
  if (options.disabled) return unavailable(action, "isn't available while the picker is disabled", { event })
  if (!options.slider) return unavailable(action, "isn't available: the dial isn't ready", { event })
  return options.slider
}

/** A prism hue picker's agent surface: the dial is UI SDK's slider, in nanometres; these name a colour by its light. */
const prismPicker = definePrimitive({
  name: "prism-picker",
  options: { slider: "value", disabled: "value" },
  // Not `disabled`: the bridge would hide every action from a disabled part without saying why.
  state: (options: PrismPickerOptions) => ({ inert: Boolean(options.disabled) }),
  sync: (options) => ({ inert: Boolean(options.disabled) }),
  api: (context) => ({
    /** Turns the prism until `nanometres` (380 to 700) leaves through the slit. */
    setWavelength(nanometres: number, event?: Event) {
      const call = { action: "setWavelength", event }
      const slider = ready(context.options(), call)
      if (slider === false) return false
      if (!Number.isFinite(nanometres) || nanometres < minWavelength || nanometres > maxWavelength) {
        return unavailable(
          "setWavelength",
          `takes ${String(minWavelength)} to ${String(maxWavelength)} nm, the visible spectrum, not ${String(nanometres)}`,
          { event },
        )
      }
      return toWavelength(slider, Math.round(nanometres), call)
    },
    /** Turns the prism to the wavelength whose colour has this OKLCH hue, in degrees. */
    setHue(degrees: number, event?: Event) {
      const call = { action: "setHue", event }
      const slider = ready(context.options(), call)
      if (slider === false) return false
      if (!Number.isFinite(degrees))
        return unavailable("setHue", `takes a hue in degrees, not ${String(degrees)}`, { event })
      const wavelength = wavelengthAtHue(degrees)
      if (wavelength === undefined) {
        return unavailable(
          "setHue",
          `can't reach ${String(Math.round(degrees))}°: magentas and purples mix both ends of the spectrum, so no single wavelength shows them`,
          { event },
        )
      }
      return toWavelength(slider, Math.round(wavelength), call)
    },
  }),
  slots: (slot) => ({
    root: slot({
      role: "group",
      attrs: (state) => ({ "data-disabled": state.inert ? "" : undefined }),
    }),
  }),
  agent: { actions: ["setWavelength", "setHue"] },
})

export { prismPicker }
export type { PrismPickerOptions, PrismSlider }

import {
  colourAtHue,
  hueAtWavelength,
  maxWavelength,
  minWavelength,
  rotationForWavelength,
  scaleAt,
  slitDirection,
  wavelengthAtScale,
  type PickedColour,
} from "@/components/ui/prism-picker-optics"

/** The scene is tilted so the white beam falls in from the upper left and the picked ray rises to the right. */
const sceneTilt = -slitDirection / 2

// Dial angles in screen degrees, clockwise from three o'clock. The spectrum runs under the prism from the violet end,
// left, to the red end, right, and leaves the top open, where the beams cross the ring.
const violetAngle = 180 + sceneTilt - 16
const redAngle = -sceneTilt + 16
const spectralSweep = violetAngle - redAngle

type Reading = {
  /** The picked wavelength in nm; fractions while the prism glides between two. */
  wavelength: number
  /** The prism's rotation in degrees. */
  rotation: number
  colour: PickedColour
}

const clampWavelength = (wavelength: number) => Math.min(maxWavelength, Math.max(minWavelength, wavelength))

/** The colour a wavelength shows: the same for the rays, the swatch, the hex and the hue readout. */
const colourAt = (wavelength: number) => colourAtHue(hueAtWavelength(clampWavelength(wavelength)))

// A glide asks for fractional wavelengths on every frame; the rotation is a 40-step search, so it is kept per
// quarter nanometre.
const rotationCache = new Map<number, number>()
function rotationAt(wavelength: number) {
  const key = Math.round(clampWavelength(wavelength) * 4) / 4
  let rotation = rotationCache.get(key)
  if (rotation === undefined) {
    rotation = rotationForWavelength(key)
    rotationCache.set(key, rotation)
  }
  return rotation
}

function readingAt(wavelength: number): Reading {
  const clamped = clampWavelength(wavelength)
  return { wavelength: clamped, rotation: rotationAt(clamped), colour: colourAt(clamped) }
}

/** The dial angle, in screen degrees, of a wavelength. */
const angleAt = (wavelength: number) => violetAngle - scaleAt(clampWavelength(wavelength)) * spectralSweep

/** The whole nanometre under a dial angle. In the open gap over the top it keeps the end the pointer came from. */
function wavelengthAtAngle(angle: number, previous: number) {
  const along = (((violetAngle - angle) % 360) + 360) % 360
  if (along <= spectralSweep) return Math.round(wavelengthAtScale(along / spectralSweep))
  return previous >= (minWavelength + maxWavelength) / 2 ? maxWavelength : minWavelength
}

type ColourNames = {
  red: string
  orange: string
  yellow: string
  green: string
  cyan: string
  blue: string
  violet: string
}

// By OKLCH hue, which the shown colour carries.
function colourName(hue: number, names: ColourNames) {
  if (hue < 40 || hue >= 330) return names.red
  if (hue < 72) return names.orange
  if (hue < 115) return names.yellow
  if (hue < 168) return names.green
  if (hue < 222) return names.cyan
  if (hue < 278) return names.blue
  return names.violet
}

export { angleAt, colourAt, colourName, readingAt, sceneTilt, wavelengthAtAngle }
export type { ColourNames, Reading }

// The optics behind the prism picker: a ray traced through a glass prism with Snell's law, the glass's index from a
// Cauchy dispersion curve, and a wavelength's colour from the CIE 1931 observer through OKLab to sRGB.

type Vec = { x: number; y: number }

/** The visible range the dial covers, in nanometres. */
const minWavelength = 380
const maxWavelength = 700

// A flint-like glass (n_d ≈ 1.57) with an Abbe number near 12, about twice the dispersion of the densest real flints
// (N-SF66, Abbe 21). The exaggeration is deliberate: with real glass the fan spans about 10° and reads as a thin
// smear at a card's size. Everything else is plain Snell's law, so the fan, its order and its total internal
// reflection near the red end still behave as a real prism's would.
const cauchyA = 1.5
const cauchyB = 0.025

/** The glass's refractive index at a wavelength in nm: n(λ) = A + B / λ², with λ in µm. */
function refractiveIndex(wavelength: number) {
  const micrometres = wavelength / 1000
  return cauchyA + cauchyB / (micrometres * micrometres)
}

// Wyman, Sloan and Shirley (2013), "Simple Analytic Approximations to the CIE XYZ Color Matching Functions": the
// multi-lobe fit, within the observer's own noise across the visible range.
const lobe = (wavelength: number, mean: number, below: number, above: number) => {
  const t = (wavelength - mean) / (wavelength < mean ? below : above)
  return Math.exp(-0.5 * t * t)
}

function cieXyz(wavelength: number): [number, number, number] {
  const x =
    1.056 * lobe(wavelength, 599.8, 37.9, 31) +
    0.362 * lobe(wavelength, 442, 16, 26.7) -
    0.065 * lobe(wavelength, 501.1, 20.4, 26.2)
  const y = 0.821 * lobe(wavelength, 568.8, 46.9, 40.5) + 0.286 * lobe(wavelength, 530.9, 16.3, 31.1)
  const z = 1.217 * lobe(wavelength, 437, 11.8, 36) + 0.681 * lobe(wavelength, 459, 26, 13.8)
  return [x, y, z]
}

/** The luminous efficiency V(λ) = ȳ(λ), 1 near 555 nm. */
const luminousEfficiency = (wavelength: number) => cieXyz(wavelength)[1]

// Björn Ottosson's XYZ (D65) to OKLab, and linear sRGB to OKLab.
function xyzToOklab([x, y, z]: [number, number, number]): [number, number, number] {
  const l = Math.cbrt(0.818_933_010_1 * x + 0.361_866_742_4 * y - 0.128_859_713_7 * z)
  const m = Math.cbrt(0.032_984_543_6 * x + 0.929_311_871_5 * y + 0.036_145_638_7 * z)
  const s = Math.cbrt(0.048_200_301_8 * x + 0.264_366_269_1 * y + 0.633_851_707 * z)
  return [
    0.210_454_255_3 * l + 0.793_617_785 * m - 0.004_072_046_8 * s,
    1.977_998_495_1 * l - 2.428_592_205 * m + 0.450_593_709_9 * s,
    0.025_904_037_1 * l + 0.782_771_766_2 * m - 0.808_675_766 * s,
  ]
}

function linearSrgbToOklab(red: number, green: number, blue: number): [number, number, number] {
  const l = Math.cbrt(0.412_221_470_8 * red + 0.536_332_536_3 * green + 0.051_445_992_9 * blue)
  const m = Math.cbrt(0.211_903_498_2 * red + 0.680_699_545_1 * green + 0.107_396_956_6 * blue)
  const s = Math.cbrt(0.088_302_461_9 * red + 0.281_718_837_6 * green + 0.629_978_700_5 * blue)
  return [
    0.210_454_255_3 * l + 0.793_617_785 * m - 0.004_072_046_8 * s,
    1.977_998_495_1 * l - 2.428_592_205 * m + 0.450_593_709_9 * s,
    0.025_904_037_1 * l + 0.782_771_766_2 * m - 0.808_675_766 * s,
  ]
}

const degrees = (radians: number) => (radians * 180) / Math.PI
const wrap = (angle: number) => ((angle % 360) + 360) % 360
const oklabHue = ([, a, b]: [number, number, number]) => wrap(degrees(Math.atan2(b, a)))

/** The OKLCH hue of the spectral colour at a wavelength: where the CIE observer places it, before any gamut. */
const spectralHue = (wavelength: number) => oklabHue(xyzToOklab(cieXyz(wavelength)))

// The most saturated sRGB colours lie on the six cube edges between the primaries and secondaries; t runs along
// them from red (0) through yellow, green, cyan, blue and magenta (5) back to red (6), in linear light.
function edgeColour(t: number): [number, number, number] {
  const segment = Math.floor(t) % 6
  const f = t - Math.floor(t)
  switch (segment) {
    case 0:
      return [1, f, 0]
    case 1:
      return [1 - f, 1, 0]
    case 2:
      return [0, 1, f]
    case 3:
      return [0, 1 - f, 1]
    case 4:
      return [f, 0, 1]
    default:
      return [1, 0, 1 - f]
  }
}

const redHue = oklabHue(linearSrgbToOklab(1, 0, 0))
const unwrappedEdgeHue = (t: number) => {
  const hue = oklabHue(linearSrgbToOklab(...edgeColour(t)))
  return hue < redHue - 1e-9 ? hue + 360 : hue
}

/**
 * The sRGB colour at the gamut's cusp for an OKLCH hue: the most chroma the screen shows at that hue, at the
 * lightness where it peaks. Its own hue is `hue`, so the swatch, the rays and the readout agree.
 */
function cuspColour(hue: number): [number, number, number] {
  let target = wrap(hue)
  if (target < redHue) target += 360
  let low = 0
  let high = 6
  for (let step = 0; step < 32; step++) {
    const middle = (low + high) / 2
    if (unwrappedEdgeHue(middle) < target) low = middle
    else high = middle
  }
  return edgeColour((low + high) / 2)
}

const encode = (linear: number) => {
  const value = Math.min(1, Math.max(0, linear))
  return value <= 0.003_130_8 ? 12.92 * value : 1.055 * value ** (1 / 2.4) - 0.055
}

type Rgb = [number, number, number]

/** Gamma-encoded sRGB, 0 to 1. */
const toSrgb = ([red, green, blue]: Rgb): Rgb => [encode(red), encode(green), encode(blue)]

const toHex = (srgb: Rgb) =>
  `#${srgb
    .map((channel) =>
      Math.round(channel * 255)
        .toString(16)
        .padStart(2, "0"),
    )
    .join("")}`

function hslHue([red, green, blue]: Rgb) {
  const max = Math.max(red, green, blue)
  const min = Math.min(red, green, blue)
  const delta = max - min
  if (delta === 0) return 0
  const hue =
    max === red ? ((green - blue) / delta) % 6 : max === green ? (blue - red) / delta + 2 : (red - green) / delta + 4
  return wrap(hue * 60)
}

type PickedColour = {
  /** The OKLCH hue, the same for the spectral colour and the sRGB one shown. */
  hue: number
  /** The HSL hue of the shown sRGB colour. */
  hslHue: number
  hex: string
  /** Gamma-encoded sRGB, 0 to 1. */
  srgb: Rgb
}

function colourAtHue(hue: number): PickedColour {
  const srgb = toSrgb(cuspColour(hue))
  return { hue: wrap(hue), hslHue: hslHue(srgb), hex: toHex(srgb), srgb }
}

// The observer's chromaticity barely moves below 420 nm and above 650 nm (and the analytic fit drifts there), so
// the hue holds at both ends, and each wavelength keeps at least the hue of the next so setHue finds one answer.
const flatBelow = 420
const flatAbove = 650

// The long end of the spectrum sits a few degrees past sRGB's red primary, toward magenta, so its cusp colour is a
// crimson (#ff003b). Hues below orange are stretched onto sRGB red's own hue, so the red end shows #ff0000 and the
// rays, swatch, hex and readout still come from this one table.
const redAnchor = 60

const hueTable = (() => {
  const table = new Float64Array(maxWavelength - minWavelength + 1)
  let previous = Infinity
  for (let index = 0; index < table.length; index++) {
    const wavelength = Math.min(flatAbove, Math.max(flatBelow, minWavelength + index))
    previous = Math.min(previous, spectralHue(wavelength))
    table[index] = previous
  }
  const spectralRed = table.at(-1) ?? 0
  return table.map((hue) =>
    hue >= redAnchor ? hue : redHue + ((hue - spectralRed) * (redAnchor - redHue)) / (redAnchor - spectralRed),
  )
})()

/** The hues the dial shows fall as the wavelength rises, from violet near 299° to sRGB red's 29°. */
const violetHue = hueTable[0] ?? 0
const redEndHue = hueTable.at(-1) ?? 0

// The dial's scale, like a prism spectroscope's, isn't even in nanometres: a nanometre takes room in proportion to
// how far it moves the hue, plus a floor, so the ends where the hue holds still stay short but reachable.
const scaleFloor = 0.35
const scaleTable = (() => {
  const steps = hueTable.length - 1
  const span = (hueTable[0] ?? 0) - (hueTable[steps] ?? 0)
  const table = new Float64Array(hueTable.length)
  let total = 0
  for (let index = 1; index <= steps; index++) {
    total += scaleFloor * (span / steps) + ((hueTable[index - 1] ?? 0) - (hueTable[index] ?? 0))
    table[index] = total
  }
  return table.map((value) => value / total)
})()

/** Where a wavelength sits along the dial's spectral arc, from 0 (380 nm) to 1 (700 nm). */
function scaleAt(wavelength: number) {
  const position = Math.min(maxWavelength, Math.max(minWavelength, wavelength)) - minWavelength
  const index = Math.min(scaleTable.length - 2, Math.floor(position))
  const f = position - index
  return (scaleTable[index] ?? 0) * (1 - f) + (scaleTable[index + 1] ?? 0) * f
}

/** The wavelength at a point of the dial's spectral arc, from 0 to 1. */
function wavelengthAtScale(fraction: number) {
  let low = minWavelength
  let high = maxWavelength
  for (let step = 0; step < 24; step++) {
    const middle = (low + high) / 2
    if (scaleAt(middle) < fraction) low = middle
    else high = middle
  }
  return (low + high) / 2
}

/** The hue a wavelength shows, read from the table between whole nanometres. */
function hueAtWavelength(wavelength: number) {
  const position = Math.min(maxWavelength, Math.max(minWavelength, wavelength)) - minWavelength
  const index = Math.floor(position)
  const next = Math.min(hueTable.length - 1, index + 1)
  const f = position - index
  return (hueTable[index] ?? 0) * (1 - f) + (hueTable[next] ?? 0) * f
}

/** The wavelength whose hue is closest to `hue`, or `undefined` for a non-spectral one (magentas and purples). */
function wavelengthAtHue(hue: number): number | undefined {
  const target = wrap(hue)
  const top = hueTable[0] ?? 0
  const bottom = hueTable.at(-1) ?? 0
  if (target > top + 0.5 || target < bottom - 0.5) return undefined
  const clamped = Math.min(top, Math.max(bottom, target))
  let low = minWavelength
  let high = maxWavelength
  for (let step = 0; step < 24; step++) {
    const middle = (low + high) / 2
    if (hueAtWavelength(middle) > clamped) low = middle
    else high = middle
  }
  return (low + high) / 2
}

// The prism: equilateral, apex down so the beam bends up, turned by `rotation` degrees about its centroid. Lengths
// are fractions of the stage's half-size.
const prismRadius = 0.27
const beamHeight = 0.06
/** The picked ray's fixed direction, in degrees, clockwise from the beam: the exit slit sits there. */
const slitDirection = -56

function prismVertices(rotation: number): [Vec, Vec, Vec] {
  const vertex = (angle: number) => {
    const radians = ((angle + rotation) * Math.PI) / 180
    return { x: prismRadius * Math.cos(radians), y: prismRadius * Math.sin(radians) }
  }
  return [vertex(90), vertex(210), vertex(330)]
}

const dot = (a: Vec, b: Vec) => a.x * b.x + a.y * b.y

function hit(origin: Vec, direction: Vec, a: Vec, b: Vec) {
  const edge = { x: b.x - a.x, y: b.y - a.y }
  const denominator = direction.x * edge.y - direction.y * edge.x
  if (Math.abs(denominator) < 1e-12) return undefined
  const offset = { x: a.x - origin.x, y: a.y - origin.y }
  const t = (offset.x * edge.y - offset.y * edge.x) / denominator
  const u = (offset.x * direction.y - offset.y * direction.x) / denominator
  return t > 1e-9 && u >= 0 && u <= 1 ? t : undefined
}

function refract(direction: Vec, normal: Vec, ratio: number): Vec | undefined {
  const cosine = -dot(normal, direction)
  const k = 1 - ratio * ratio * (1 - cosine * cosine)
  if (k < 0) return undefined
  const factor = ratio * cosine - Math.sqrt(k)
  return { x: ratio * direction.x + factor * normal.x, y: ratio * direction.y + factor * normal.y }
}

type Trace = {
  /** Where the beam meets the prism, where it leaves, and the exit direction (a unit vector). */
  entry: Vec
  exit: Vec
  direction: Vec
  /** The ray's way through the glass: the entry, any reflections off a face, and the exit. */
  path: Vec[]
  /** Set when the ray reflects off the far face instead of leaving it. */
  reflected: boolean
  /** The direction of the few per cent the entry face reflects. */
  glint: Vec
}

/** Traces one wavelength from the stage's left edge through the prism turned by `rotation` degrees. */
function trace(rotation: number, wavelength: number): Trace | undefined {
  const [first, second, third] = prismVertices(rotation)
  const edges: [Vec, Vec][] = [
    [first, second],
    [second, third],
    [third, first],
  ]
  const n = refractiveIndex(wavelength)
  let origin: Vec = { x: -2, y: beamHeight }
  let direction: Vec = { x: 1, y: 0 }
  let inside = false
  let glint: Vec | undefined
  const path: Vec[] = []
  let reflected = false
  let lastEdge = -1
  for (let bounce = 0; bounce < 4; bounce++) {
    let nearest = Infinity
    let edgeIndex = -1
    edges.forEach(([start, end], index) => {
      if (index === lastEdge) return
      const t = hit(origin, direction, start, end)
      if (t !== undefined && t < nearest) {
        nearest = t
        edgeIndex = index
      }
    })
    const edge = edges[edgeIndex]
    if (!edge) return undefined
    const [a, b] = edge
    const point = { x: origin.x + direction.x * nearest, y: origin.y + direction.y * nearest }
    const length = Math.hypot(b.x - a.x, b.y - a.y)
    let normal = { x: (b.y - a.y) / length, y: -(b.x - a.x) / length }
    if (dot(normal, direction) > 0) normal = { x: -normal.x, y: -normal.y }
    if (!inside) {
      const bent = refract(direction, normal, 1 / n)
      if (!bent) return undefined
      const along = 2 * dot(direction, normal)
      glint = { x: direction.x - along * normal.x, y: direction.y - along * normal.y }
      path.push(point)
      direction = bent
      inside = true
    } else {
      const bent = refract(direction, normal, n)
      if (bent) {
        const entry = path[0]
        if (!entry || !glint) return undefined
        path.push(point)
        return { entry, exit: point, direction: bent, path, reflected, glint }
      }
      const along = 2 * dot(direction, normal)
      direction = { x: direction.x - along * normal.x, y: direction.y - along * normal.y }
      path.push(point)
      reflected = true
    }
    origin = point
    lastEdge = edgeIndex
  }
  return undefined
}

const exitAngle = (rotation: number, wavelength: number) => {
  const traced = trace(rotation, wavelength)
  return traced ? degrees(Math.atan2(traced.direction.y, traced.direction.x)) : undefined
}

// The rotations the dial drives the prism through: on this side of minimum deviation, the exit angle of every
// wavelength rises steadily with the rotation, so each wavelength reaches the slit at one rotation.
const rotationRange = { low: -26, high: 0 }

/** The prism's rotation, in degrees, that sends `wavelength` out along the slit's direction. */
function rotationForWavelength(wavelength: number) {
  let low = rotationRange.low
  let high = rotationRange.high
  for (let step = 0; step < 40; step++) {
    const middle = (low + high) / 2
    const angle = exitAngle(middle, wavelength)
    if (angle === undefined || angle < slitDirection) high = middle
    else low = middle
  }
  return (low + high) / 2
}

export {
  colourAtHue,
  cieXyz,
  exitAngle,
  hueAtWavelength,
  luminousEfficiency,
  maxWavelength,
  minWavelength,
  prismRadius,
  prismVertices,
  redEndHue,
  refractiveIndex,
  rotationForWavelength,
  rotationRange,
  slitDirection,
  spectralHue,
  trace,
  violetHue,
  wavelengthAtHue,
  scaleAt,
  wavelengthAtScale,
  beamHeight,
}
export type { PickedColour, Rgb, Trace, Vec }

// Paints the light: the white beam, the glass, the dispersed fan and the picked ray, additively. Thin lines go to
// the canvas at device resolution; the fan, a soft field of colour, to a buffer at half the CSS size; the bloom to
// one at a quarter, which the hook blurs. Rasterized on a CPU, the fan at full size was most of a frame.

import { colourAt, sceneTilt, type Reading } from "@/components/ui/prism-picker-dial"
import {
  luminousEfficiency,
  maxWavelength,
  minWavelength,
  prismRadius,
  prismVertices,
  trace,
  type Rgb,
  type Vec,
} from "@/components/ui/prism-picker-optics"

/** The stage's layout, shared with the dial's CSS: the prism's centre and the ring's radius, in CSS px. */
const stageCentre = { x: 0.5, y: 0.58 }
const ringRadius = (width: number, height: number) => Math.min(height * 0.31, width * 0.3)
const prismScale = 0.56

type Layout = { cx: number; cy: number; ring: number; scale: number; width: number; height: number }

function layoutFor(width: number, height: number): Layout {
  const ring = ringRadius(width, height)
  return {
    cx: width * stageCentre.x,
    cy: height * stageCentre.y,
    ring,
    scale: (ring * prismScale) / prismRadius,
    width,
    height,
  }
}

const tiltRadians = (sceneTilt * Math.PI) / 180
const tiltCos = Math.cos(tiltRadians)
const tiltSin = Math.sin(tiltRadians)
const turn = (v: Vec): Vec => ({ x: v.x * tiltCos - v.y * tiltSin, y: v.x * tiltSin + v.y * tiltCos })

const toScreen = (layout: Layout, p: Vec): Vec => {
  const turned = turn(p)
  return { x: layout.cx + turned.x * layout.scale, y: layout.cy + turned.y * layout.scale }
}

/** How far a ray from `p` along unit `d` travels before it leaves the stage. */
function toEdge(layout: Layout, p: Vec, d: Vec) {
  let t = Infinity
  if (d.x > 1e-9) t = Math.min(t, (layout.width - p.x) / d.x)
  if (d.x < -1e-9) t = Math.min(t, -p.x / d.x)
  if (d.y > 1e-9) t = Math.min(t, (layout.height - p.y) / d.y)
  if (d.y < -1e-9) t = Math.min(t, -p.y / d.y)
  return Number.isFinite(t) ? Math.max(0, t) : 0
}

const along = (p: Vec, d: Vec, t: number): Vec => ({ x: p.x + d.x * t, y: p.y + d.y * t })

const rgba = ([red, green, blue]: Rgb, alpha: number) =>
  `rgba(${String(Math.round(red * 255))},${String(Math.round(green * 255))},${String(Math.round(blue * 255))},${String(Math.max(0, Math.min(1, alpha)))})`

const towardWhite = ([red, green, blue]: Rgb, amount: number): Rgb => [
  red + (1 - red) * amount,
  green + (1 - green) * amount,
  blue + (1 - blue) * amount,
]

const fanStep = 4
const glowStride = 8
const reflectedStride = 4
// The ends of the spectrum are dim to the eye; a floor keeps them visible on the dial.
const fan = Array.from({ length: (maxWavelength - minWavelength) / fanStep + 1 }, (_, index) => {
  const wavelength = minWavelength + index * fanStep
  return {
    wavelength,
    colour: colourAt(wavelength).srgb,
    weight: 0.45 + 0.55 * Math.sqrt(luminousEfficiency(wavelength)),
  }
})

const white: Rgb = [1, 1, 1]

type Painter = { sharp: CanvasRenderingContext2D; glow: CanvasRenderingContext2D; layout: Layout }

function line(context: CanvasRenderingContext2D, from: Vec, to: Vec, width: number, style: string | CanvasGradient) {
  context.beginPath()
  context.moveTo(from.x, from.y)
  context.lineTo(to.x, to.y)
  context.lineWidth = width
  context.strokeStyle = style
  context.stroke()
}

function fade(context: CanvasRenderingContext2D, from: Vec, to: Vec, colour: Rgb, start: number, end: number) {
  const gradient = context.createLinearGradient(from.x, from.y, to.x, to.y)
  gradient.addColorStop(0, rgba(colour, start))
  gradient.addColorStop(0.55, rgba(colour, start * 0.5 + end * 0.5))
  gradient.addColorStop(1, rgba(colour, end))
  return gradient
}

function paintBeam({ sharp, glow, layout }: Painter, entry: Vec) {
  const direction = turn({ x: 1, y: 0 })
  const start = along(entry, direction, -toEdge(layout, entry, { x: -direction.x, y: -direction.y }))
  const normal = { x: -direction.y, y: direction.x }
  line(glow, start, entry, 7, "rgba(255,255,255,0.55)")
  line(sharp, start, entry, 3, "rgba(255,255,255,0.22)")
  // Faint chromatic fringes on either side of the core, as a lens would leave them.
  line(sharp, along(start, normal, 1.1), along(entry, normal, 1.1), 0.8, "rgba(255,90,70,0.32)")
  line(sharp, along(start, normal, -1.1), along(entry, normal, -1.1), 0.8, "rgba(80,140,255,0.36)")
  line(sharp, start, entry, 1.1, "rgba(255,255,255,0.95)")
}

function paintGlass({ sharp, glow, layout }: Painter, rotation: number, entry: Vec) {
  const [apexVertex, leftVertex, rightVertex] = prismVertices(rotation)
  const apex = toScreen(layout, apexVertex)
  const left = toScreen(layout, leftVertex)
  const right = toScreen(layout, rightVertex)
  const corners = [apex, left, right]
  const outline = (context: CanvasRenderingContext2D, inset = 0) => {
    const centre = { x: (apex.x + left.x + right.x) / 3, y: (apex.y + left.y + right.y) / 3 }
    context.beginPath()
    corners.forEach((corner, index) => {
      const distance = Math.hypot(corner.x - centre.x, corner.y - centre.y)
      const k = (distance - inset) / distance
      const point = { x: centre.x + (corner.x - centre.x) * k, y: centre.y + (corner.y - centre.y) * k }
      if (index === 0) context.moveTo(point.x, point.y)
      else context.lineTo(point.x, point.y)
    })
    context.closePath()
  }
  const body = sharp.createLinearGradient(left.x, left.y, apex.x, apex.y)
  body.addColorStop(0, "rgba(255,255,255,0.09)")
  body.addColorStop(0.5, "rgba(170,190,255,0.035)")
  body.addColorStop(1, "rgba(255,255,255,0.06)")
  outline(sharp)
  sharp.fillStyle = body
  sharp.fill()
  outline(sharp, 3.5)
  sharp.lineWidth = 1
  sharp.strokeStyle = "rgba(255,255,255,0.07)"
  sharp.stroke()
  outline(sharp)
  sharp.lineWidth = 1
  sharp.strokeStyle = "rgba(255,255,255,0.3)"
  sharp.stroke()
  // The top face catches the light along its middle; the exit face carries a faint red and blue edge.
  const highlight = sharp.createLinearGradient(left.x, left.y, right.x, right.y)
  highlight.addColorStop(0, "rgba(255,255,255,0)")
  highlight.addColorStop(0.45, "rgba(255,255,255,0.75)")
  highlight.addColorStop(1, "rgba(255,255,255,0)")
  line(sharp, left, right, 1.4, highlight)
  const edge = { x: apex.x - right.x, y: apex.y - right.y }
  const length = Math.hypot(edge.x, edge.y)
  const outward = { x: edge.y / length, y: -edge.x / length }
  line(sharp, along(right, outward, -0.9), along(apex, outward, -0.9), 0.9, "rgba(255,80,90,0.28)")
  line(sharp, along(right, outward, 0.9), along(apex, outward, 0.9), 0.9, "rgba(90,150,255,0.28)")
  for (const corner of corners) {
    const flare = glow.createRadialGradient(corner.x, corner.y, 0, corner.x, corner.y, 5)
    flare.addColorStop(0, "rgba(255,255,255,0.35)")
    flare.addColorStop(1, "rgba(255,255,255,0)")
    glow.fillStyle = flare
    glow.fillRect(corner.x - 5, corner.y - 5, 10, 10)
  }
  const spark = sharp.createRadialGradient(entry.x, entry.y, 0, entry.x, entry.y, 9)
  spark.addColorStop(0, "rgba(255,255,255,0.9)")
  spark.addColorStop(1, "rgba(255,255,255,0)")
  sharp.fillStyle = spark
  sharp.fillRect(entry.x - 9, entry.y - 9, 18, 18)
}

function paintDot({ sharp, glow }: Painter, at: Vec, colour: Rgb) {
  const halo = glow.createRadialGradient(at.x, at.y, 0, at.x, at.y, 26)
  halo.addColorStop(0, rgba(towardWhite(colour, 0.3), 1))
  halo.addColorStop(0.4, rgba(colour, 0.7))
  halo.addColorStop(1, rgba(colour, 0))
  glow.fillStyle = halo
  glow.fillRect(at.x - 26, at.y - 26, 52, 52)
  const core = sharp.createRadialGradient(at.x, at.y, 0, at.x, at.y, 11)
  core.addColorStop(0, "rgba(255,255,255,1)")
  core.addColorStop(0.28, rgba(towardWhite(colour, 0.5), 1))
  core.addColorStop(0.6, rgba(colour, 0.55))
  core.addColorStop(1, rgba(colour, 0))
  sharp.fillStyle = core
  sharp.fillRect(at.x - 11, at.y - 11, 22, 22)
}

/** The slit's mount: a ring and two jaws across the picked ray where it meets the stage's edge. */
function paintSlit({ sharp }: Painter, at: Vec, direction: Vec) {
  const normal = { x: -direction.y, y: direction.x }
  sharp.globalCompositeOperation = "source-over"
  for (const side of [1, -1]) {
    const from = along(at, normal, side * 15)
    line(sharp, from, along(from, normal, side * 9), 1, "rgba(255,255,255,0.42)")
  }
  sharp.beginPath()
  sharp.arc(at.x, at.y, 15, 0, Math.PI * 2)
  sharp.lineWidth = 1
  sharp.strokeStyle = "rgba(255,255,255,0.14)"
  sharp.stroke()
  sharp.globalCompositeOperation = "lighter"
}

type FanRay = {
  wavelength: number
  colour: Rgb
  weight: number
  traced: NonNullable<ReturnType<typeof trace>>
  exit: Vec
  direction: Vec
  far: Vec
}

// One fill for the whole fan: a conic gradient from the rays' common exit, a stop per ray in its colour, then one
// radial fade with distance. Eighty wedges, each its own gradient, were most of a frame on a CPU.
function paintFan(context: CanvasRenderingContext2D, rays: FanRay[], level: number) {
  const first = rays[0]
  const last = rays.at(-1)
  if (!first || !last || rays.length < 2) return
  const origin = {
    x: rays.reduce((sum, ray) => sum + ray.exit.x, 0) / rays.length,
    y: rays.reduce((sum, ray) => sum + ray.exit.y, 0) / rays.length,
  }
  const angleOf = (ray: FanRay) => Math.atan2(ray.far.y - origin.y, ray.far.x - origin.x)
  const sorted = rays.toSorted((a, b) => angleOf(a) - angleOf(b))
  const start = angleOf(sorted[0]!) - 0.05
  const conic = context.createConicGradient(start, origin.x, origin.y)
  for (const ray of sorted) {
    const turned = (((angleOf(ray) - start) % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2)
    conic.addColorStop(turned / (Math.PI * 2), rgba(ray.colour, ray.weight * level))
  }
  context.beginPath()
  context.moveTo(first.exit.x, first.exit.y)
  for (const ray of rays) context.lineTo(ray.exit.x, ray.exit.y)
  for (const ray of rays.toReversed()) context.lineTo(ray.far.x, ray.far.y)
  context.closePath()
  context.fillStyle = conic
  context.fill()
  // The shortest ray sets the fade, so the rays that leave through the top dim at the edge as the long ones do.
  const reach = Math.min(...rays.map((ray) => Math.hypot(ray.far.x - origin.x, ray.far.y - origin.y)))
  const falloff = context.createRadialGradient(origin.x, origin.y, 0, origin.x, origin.y, reach)
  falloff.addColorStop(0, "rgba(0,0,0,1)")
  falloff.addColorStop(0.55, "rgba(0,0,0,0.58)")
  falloff.addColorStop(1, "rgba(0,0,0,0.16)")
  context.globalCompositeOperation = "destination-in"
  context.fillStyle = falloff
  context.fillRect(0, 0, context.canvas.width * 4, context.canvas.height * 4)
  context.globalCompositeOperation = "lighter"
}

// The rays inside the glass, from the entry to where each leaves: one thin triangle with their colours across it.
function paintSheen(context: CanvasRenderingContext2D, entry: Vec, rays: FanRay[]) {
  const first = rays[0]
  const last = rays.at(-1)
  if (!first || !last || rays.length < 2) return
  const across = context.createLinearGradient(first.exit.x, first.exit.y, last.exit.x, last.exit.y)
  rays.forEach((ray, index) => {
    if (index % 4 === 0 || ray === last)
      across.addColorStop(index / (rays.length - 1), rgba(ray.colour, 0.22 * ray.weight))
  })
  context.beginPath()
  context.moveTo(entry.x, entry.y)
  context.lineTo(first.exit.x, first.exit.y)
  context.lineTo(last.exit.x, last.exit.y)
  context.closePath()
  context.fillStyle = across
  context.fill()
}

/** The three contexts a scene paints into: thin lines at full resolution, the fan at half, the glow at a quarter. */
type SceneTargets = { sharp: CanvasRenderingContext2D; field: CanvasRenderingContext2D; glow: CanvasRenderingContext2D }

function paintScene({ sharp, field, glow }: SceneTargets, layout: Layout, reading: Reading) {
  const painter: Painter = { sharp, glow, layout }
  for (const context of [sharp, field, glow]) {
    context.globalCompositeOperation = "source-over"
    context.clearRect(0, 0, layout.width, layout.height)
    context.globalCompositeOperation = "lighter"
    context.lineCap = "round"
    context.lineJoin = "round"
  }
  const rays = fan.map((ray) => ({ ...ray, traced: trace(reading.rotation, ray.wavelength) }))
  const picked = trace(reading.rotation, reading.wavelength)
  const firstTrace = rays.find((ray) => ray.traced)?.traced ?? picked
  if (!firstTrace) return
  const entry = toScreen(layout, firstTrace.entry)
  paintBeam(painter, entry)

  const glint = turn(firstTrace.glint)
  const glintEnd = along(entry, glint, layout.ring * 0.6)
  line(sharp, entry, glintEnd, 1, fade(sharp, entry, glintEnd, white, 0.14, 0))

  const fanLevel = 0.85
  const screenRays = rays.map((ray): FanRay | undefined => {
    const { traced } = ray
    if (!traced) return undefined
    const exit = toScreen(layout, traced.exit)
    const direction = turn(traced.direction)
    return { ...ray, traced, exit, direction, far: along(exit, direction, toEdge(layout, exit, direction)) }
  })

  const lit = screenRays.filter((ray): ray is FanRay => ray !== undefined && !ray.traced.reflected)
  paintFan(field, lit, 0.5 * fanLevel)

  // The glow is blurred, so a wedge every few rays is enough.
  for (let index = 0; index + glowStride < screenRays.length; index += glowStride) {
    const ray = screenRays[index]
    const edge = screenRays[index + glowStride]
    if (!ray || !edge || ray.traced.reflected || edge.traced.reflected) continue
    const level = ((ray.weight + edge.weight) / 2) * fanLevel * 0.85
    glow.beginPath()
    glow.moveTo(ray.exit.x, ray.exit.y)
    glow.lineTo(edge.exit.x, edge.exit.y)
    glow.lineTo(edge.far.x, edge.far.y)
    glow.lineTo(ray.far.x, ray.far.y)
    glow.closePath()
    glow.fillStyle = fade(glow, ray.exit, ray.far, ray.colour, level, level * 0.16)
    glow.fill()
  }

  paintSheen(sharp, toScreen(layout, firstTrace.entry), lit)
  // Rays the far face reflects leave faintly through another face; a few of them draw that.
  screenRays.forEach((ray, index) => {
    if (!ray?.traced.reflected || index % reflectedStride !== 0) return
    const level = 0.035 * reflectedStride * ray.weight
    line(sharp, ray.exit, ray.far, 1, fade(sharp, ray.exit, ray.far, ray.colour, level, 0))
  })
  glow.beginPath()
  firstTrace.path.forEach((point, index) => {
    const screen = toScreen(layout, point)
    if (index === 0) glow.moveTo(screen.x, screen.y)
    else glow.lineTo(screen.x, screen.y)
  })
  glow.lineWidth = 6
  glow.strokeStyle = "rgba(255,255,255,0.28)"
  glow.stroke()

  paintGlass(painter, reading.rotation, entry)

  if (!picked) return
  const colour = reading.colour.srgb
  const path = picked.path.map((point) => toScreen(layout, point))
  const exit = path.at(-1) ?? entry
  const direction = turn(picked.direction)
  const end = along(exit, direction, toEdge(layout, exit, direction))
  const dot = along(end, direction, -16)
  sharp.beginPath()
  path.forEach((point, index) => (index === 0 ? sharp.moveTo(point.x, point.y) : sharp.lineTo(point.x, point.y)))
  sharp.lineWidth = 1.2
  sharp.strokeStyle = rgba(towardWhite(colour, 0.3), 0.6)
  sharp.stroke()
  line(glow, exit, dot, 6, rgba(colour, 0.95))
  line(sharp, exit, dot, 2.6, rgba(colour, 0.75))
  line(sharp, exit, dot, 1, rgba(towardWhite(colour, 0.6), 1))
  paintSlit(painter, dot, direction)
  paintDot(painter, dot, colour)
}

export { layoutFor, paintScene, ringRadius, stageCentre }
export type { Layout, SceneTargets }

import { useEffect, useEffectEvent, useLayoutEffect, useRef, type RefObject } from "react"

import { angleAt, readingAt } from "@/components/ui/prism-picker-dial"
import { layoutFor, paintScene } from "@/components/ui/prism-picker-scene"

type PrismCanvases = {
  stage: RefObject<HTMLElement | null>
  light: RefObject<HTMLCanvasElement | null>
}

/** Offscreen buffers: the fan at half the stage's size, and the glow at a quarter, blurred into `soft`. */
type GlowBuffers = { field: HTMLCanvasElement; glow: HTMLCanvasElement; soft: HTMLCanvasElement }

type SceneOptions = {
  /** The wavelength to show. */
  wavelength: number
  /** Jump to it, for a drag: the pointer already moves smoothly. */
  instant: boolean
  /** Called with each paint's duration in ms. */
  onPaint?: ((milliseconds: number) => void) | undefined
}

type Size = { width: number; height: number }

// A machine without a GPU (a CI runner, a VM, some remote desktops) emulates GL in software: SwiftShader, llvmpipe,
// WARP. An accelerated canvas there paints about 20 times slower than Skia on the CPU, which `willReadFrequently`
// asks for; with a real GPU the accelerated canvas is the fastest, by about 10 ms a frame at a DPR of 2. The CPU
// rasterizes every pixel, so there the canvas stays at a DPR of 1: a runner or a VM rarely shows a sharper screen.
const softwareRenderer = /swiftshader|llvmpipe|softpipe|basic render|warp/i
type CanvasPlan = { settings: CanvasRenderingContext2DSettings; maxRatio: number }
let canvasPlan: CanvasPlan | undefined

function planCanvas(): CanvasPlan {
  if (canvasPlan) return canvasPlan
  const gl = document.createElement("canvas").getContext("webgl")
  let software = true
  if (gl) {
    // Chrome and Safari report a generic RENDERER and the real one through the debug extension; Firefox reports it
    // in RENDERER and deprecates the extension.
    const generic = String(gl.getParameter(gl.RENDERER))
    const debug = generic === "WebKit WebGL" ? gl.getExtension("WEBGL_debug_renderer_info") : null
    const renderer = debug ? String(gl.getParameter(debug.UNMASKED_RENDERER_WEBGL)) : generic
    software = softwareRenderer.test(renderer)
    gl.getExtension("WEBGL_lose_context")?.loseContext()
  }
  canvasPlan = { settings: { willReadFrequently: software }, maxRatio: software ? 1 : 2 }
  return canvasPlan
}
// The glow buffer's scale: a soft field needs few pixels, and scaling it up blurs it further for free.
const glowScale = 4
// The old CSS blur(7px), in the glow buffer's pixels.
const glowBlur = `blur(${String(7 / glowScale)}px)`

// The panel duration token: a key press or an agent's step glides the prism there, a drag follows the pointer.
const glideMs = 180
const glideAbove = 2
const ease = (t: number) => 1 - (1 - t) ** 4

// The size comes from the ResizeObserver, never from the element, so a paint inside a layout effect, right after
// React wrote the DOM, doesn't force a layout.
// The knob carries its own angle and colour: set on the stage, they would restyle the whole engraved scale on
// every frame, which a compositor without a GPU felt as a dropped frame per key press.
const knobOf = (stage: HTMLElement) => stage.querySelector<HTMLElement>('[data-slot="slider-thumb"]')

function sized(canvas: HTMLCanvasElement, width: number, height: number) {
  if (canvas.width !== width) canvas.width = width
  if (canvas.height !== height) canvas.height = height
  return canvas.getContext("2d", planCanvas().settings)
}

// The glow used to be a second canvas with a CSS blur and an additive blend, which a compositor without a GPU redid
// over the whole stage on every frame. Now it is blurred at a quarter size and added into the one canvas.
function paint(canvases: PrismCanvases, buffers: GlowBuffers, size: Size | null, wavelength: number) {
  const stage = canvases.stage.current
  const lightCanvas = canvases.light.current
  if (!stage || !lightCanvas || !size || size.width < 2 || size.height < 2) return false
  const { width, height } = size
  const ratio = Math.min(planCanvas().maxRatio, devicePixelRatio || 1)
  const light = sized(lightCanvas, Math.round(width * ratio), Math.round(height * ratio))
  const fieldWidth = Math.ceil(width / 2)
  const fieldHeight = Math.ceil(height / 2)
  const field = sized(buffers.field, fieldWidth, fieldHeight)
  const glowWidth = Math.ceil(width / glowScale)
  const glowHeight = Math.ceil(height / glowScale)
  const glow = sized(buffers.glow, glowWidth, glowHeight)
  const soft = sized(buffers.soft, glowWidth, glowHeight)
  if (!light || !field || !glow || !soft) return false
  light.setTransform(ratio, 0, 0, ratio, 0, 0)
  field.setTransform(fieldWidth / width, 0, 0, fieldHeight / height, 0, 0)
  glow.setTransform(glowWidth / width, 0, 0, glowHeight / height, 0, 0)
  const reading = readingAt(wavelength)
  paintScene({ sharp: light, field, glow }, layoutFor(width, height), reading)
  soft.clearRect(0, 0, glowWidth, glowHeight)
  soft.filter = glowBlur
  soft.drawImage(buffers.glow, 0, 0)
  field.setTransform(1, 0, 0, 1, 0, 0)
  field.globalCompositeOperation = "lighter"
  field.drawImage(buffers.soft, 0, 0, fieldWidth, fieldHeight)
  light.setTransform(1, 0, 0, 1, 0, 0)
  light.globalCompositeOperation = "lighter"
  light.drawImage(buffers.field, 0, 0, lightCanvas.width, lightCanvas.height)
  // The knob follows the painted wavelength, not the value, so it glides with the prism without a React render.
  const knob = knobOf(stage)
  knob?.style.setProperty("--prism-dial", `${String(angleAt(wavelength))}deg`)
  knob?.style.setProperty("--prism-shown", reading.colour.hex)
  return true
}

// Outside the hook: React Compiler can't compile `??=`.
function glowBuffersOf(ref: { current: GlowBuffers | null }): GlowBuffers {
  if (ref.current === null) {
    ref.current = {
      field: document.createElement("canvas"),
      glow: document.createElement("canvas"),
      soft: document.createElement("canvas"),
    }
  }
  return ref.current
}

/** Paints the prism scene when the wavelength or the stage's size changes, and only then: nothing runs while idle. */
function usePrismPickerScene(canvases: PrismCanvases, { wavelength, instant, onPaint }: SceneOptions) {
  const shown = useRef<number | null>(null)
  const size = useRef<Size | null>(null)
  // Made on the first paint, in the browser: the hook also renders on the server.
  const buffers = useRef<GlowBuffers | null>(null)

  const paintAt = useEffectEvent((at: number) => {
    const started = performance.now()
    if (paint(canvases, glowBuffersOf(buffers), size.current, at)) onPaint?.(performance.now() - started)
  })
  const repaint = useEffectEvent(() => paintAt(shown.current ?? wavelength))

  useEffect(() => {
    const stage = canvases.stage.current
    if (!stage) return
    let frame = 0
    const observer = new ResizeObserver(([entry]) => {
      if (!entry) return
      size.current = { width: entry.contentRect.width, height: entry.contentRect.height }
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(repaint)
    })
    observer.observe(stage)
    return () => {
      observer.disconnect()
      cancelAnimationFrame(frame)
    }
  }, [canvases])

  // A layout effect, so a drag paints the canvas in the same frame React commits the knob and the readout.
  useLayoutEffect(() => {
    const from = shown.current
    const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches
    // An arrow key moves a nanometre or two, which a glide wouldn't show: it would only repaint for 180 ms.
    if (from === null || instant || reduced || Math.abs(wavelength - from) <= glideAbove) {
      shown.current = wavelength
      paintAt(wavelength)
      return
    }
    // The canvas still shows where the glide starts; only the knob, which React just rendered at its end, goes back.
    const stage = canvases.stage.current
    if (stage) knobOf(stage)?.style.setProperty("--prism-dial", `${String(angleAt(from))}deg`)
    const started = performance.now()
    let frame = 0
    const step = (now: number) => {
      const t = Math.min(1, (now - started) / glideMs)
      shown.current = from + (wavelength - from) * ease(t)
      paintAt(shown.current)
      if (t < 1) frame = requestAnimationFrame(step)
    }
    frame = requestAnimationFrame(step)
    return () => cancelAnimationFrame(frame)
  }, [canvases, wavelength, instant])
}

export { usePrismPickerScene }
export type { PrismCanvases }
